mapper.select:
select sh.id, sh.code, sh.name, sh.floor, sh.floor_type floorType, sh.house_property houseProperty, sh.house_function houseFunction, sh.house_status houseStatus, sh.orientation, sh.cover_area, sh.build_area, sh.park_org_id parkOrgId, sh.building_id buildingId, sp.org_name parkOrgName, sb.name buildingName, sh.remark, sb.total_floor from sys_house sh left join sys_organization sp on sp.id = sh.park_org_id left join sys_building sb on sb.id = sh.building_id where sh.deleted = 0 and sp.deleted = 0
and sp.head_org_id = #{houseListDTO.headOrgId}
and sh.park_org_id = #{houseListDTO.parkOrgId}
and sh.building_id = #{houseListDTO.buildingId}
and sh.id = #{houseListDTO.houseId}
and sh.name like CONCAT('%',#{houseListDTO.houseName},'%')
and sh.house_status = #{houseListDTO.houseStatus}
and sh.house_function = #{houseListDTO.houseFunction}
and sh.house_property <> #{houseListDTO.notHouseProperty}
and sh.id not in
#{noId}
and sh.house_status in
#{houseStatus}
and sh.park_org_id in
#{parkOrgId}
order by sh.create_time desc
order by CONVERT(sb.name USING gbk),CONVERT(sh.name USING gbk) asc
